// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.0;

/// @notice Ghost-variable harness proving: Sum_u dai[u] == debt
/// Technique: ghost accumulator `ghost_sumDai` updated on every dai mutation.
/// Sound abstraction: each Vat function's dai/debt effects are faithfully modeled;
/// functions not touching dai or debt (slip, flux, fork, grab, file, cage, init) are omitted.
contract DaiConservation {
    mapping(address => uint256) public dai;
    uint256 public debt;
    uint256 public ghost_sumDai;

    // --- Vat math (verbatim) ---
    function _add(uint x, int y) internal pure returns (uint z) {
        unchecked { z = x + uint(y); require(y >= 0 || z <= x); require(y <= 0 || z >= x); }
    }
    function _add(uint x, uint y) internal pure returns (uint z) {
        unchecked { require((z = x + y) >= x); }
    }
    function _sub(uint x, uint y) internal pure returns (uint z) {
        unchecked { require((z = x - y) <= x); }
    }

    /// Abstracts: move(src, dst, rad)
    /// dai[src] -= rad, dai[dst] += rad, debt unchanged.
    /// Ghost net change: -rad + rad = 0.
    function op_move(address src, address dst, uint256 rad) external {
        dai[src] = _sub(dai[src], rad);
        dai[dst] = _add(dai[dst], rad);
        assert(ghost_sumDai == debt);
    }

    /// Abstracts dai/debt effects of frob and fold.
    /// Both add the same signed delta to one dai slot and to debt.
    function op_dai_debt_signed(address w, int delta) external {
        dai[w]       = _add(dai[w], delta);
        debt         = _add(debt,   delta);
        ghost_sumDai = _add(ghost_sumDai, delta);
        assert(ghost_sumDai == debt);
    }

